declare(strict_types=1); require_once __DIR__.DIRECTORY_SEPARATOR.'auth.php'; admin_require_login(); send_security_headers(); header('Content-Type: text/html; charset=utf-8'); $p=db_connection(); $c=['Registered visitors'=>(int)$p->query('SELECT COUNT(*) FROM visitors')->fetchColumn(),'Uploaded photos'=>(int)$p->query('SELECT COUNT(*) FROM photos')->fetchColumn(),'Awaiting review'=>(int)$p->query("SELECT COUNT(*) FROM photos WHERE approval_status='pending'")->fetchColumn(),'Approved photos'=>(int)$p->query("SELECT COUNT(*) FROM photos WHERE approval_status='approved' AND status='active'")->fetchColumn(),'Hidden / rejected'=>(int)$p->query("SELECT COUNT(*) FROM photos WHERE status='hidden' OR approval_status='rejected'")->fetchColumn()]; echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administrator dashboard</title></head><body><h1>Administrator dashboard</h1><nav><a href="visitors.php">Visitors</a> | <a href="photos.php">Photo review</a></nav><h2>Overview</h2><ul>'; foreach($c as $k=>$v)echo '<li>'.admin_e($k).': '.$v.'</li>'; echo '</ul><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="'.admin_e(csrf_token()).'"><button>Log out</button></form></body></html>';
